// Cache en memoire : la cle est la requete, la valeur sa reponse
const cache = new Map()

async function repondre(requete) {
  // Requete deja vue ? On ressert la reponse, sans appeler le modele
  if (cache.has(requete)) return cache.get(requete)

  // Sinon on appelle le modele (c'est la partie couteuse et lente)
  const reponse = await modele(requete)

  // On memorise pour la prochaine fois
  cache.set(requete, reponse)
  return reponse
}

// 1er appel : va au modele. 2e appel identique : instantane, gratuit.
await repondre('Capitale de la France ?')
await repondre('Capitale de la France ?')
